using System.Net;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using MeowChan.Archive;
using MeowChan.Desktop;
using MeowChan.Desktop.Updates;
using MeowChan.Favorites;
using MeowChan.Persistence;
using MeowChan.Storage;

namespace MeowChan.DesktopTests;

// Requires a fresh profile generated by the isolated, pinned 0.9 executable. A skipped
// ordinary suite is deliberately not an upgrade PASS. See fixtures/upgrade-v09/README.md.
public sealed class DesktopUpgradeIntegrationTests
{
    private static readonly TimeSpan Deadline = TimeSpan.FromSeconds(45);

    [UpgradeFixtureFact]
    public async Task Genuine09ProfileMigratesToDeliveredPluginsAndRestartsTwiceOffline()
    {
        string profile = Path.GetFullPath(Environment.GetEnvironmentVariable("MEOWCHAN_V09_UPGRADE_PROFILE")!);
        using JsonDocument receipt = JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(profile, "v09-receipt.json")));
        JsonElement expected = receipt.RootElement;
        Assert.Equal("8ec0cf50b270e0551a06d3ad61eff0f448bd70ff", expected.GetProperty("SourceRevision").GetString());
        Assert.False(Directory.Exists(Path.Combine(profile, "plugin-cache")), "Use a fresh 0.9 profile; never rerun this test against an upgraded fixture.");
        Assert.True(expected.GetProperty("LegacyProfileLock").GetBoolean());
        Assert.Equal(expected.GetProperty("Protocol").GetString(), await File.ReadAllTextAsync(Path.Combine(profile, ".meowchan-profile.protocol")));
        Assert.Equal(2, expected.GetProperty("Threads").GetArrayLength());
        Dictionary<string, string>? revisions = null;
        for (int startup = 0; startup < 3; startup++)
        {
            using RejectNetwork offline = new();
            await using DesktopSessionHost host = new(profile,
                updateSessionFactory: (path, config) => new UpdateSession(path, config, offline.Client(), disableEnvironment: () => "1"),
                pluginTransportFactory: offline.Client);
            await host.StartAsync().WaitAsync(Deadline);
            Assert.True(host.State == DesktopSessionState.Ready, host.StartupError);
            Assert.True(host.IsPaused);
            Assert.NotNull(host.Plugins);
            Assert.Empty(host.Plugins.Warnings);
            Assert.Equal(new[] { "4chan", "8kun", "endchan", "kohlchan", "lainchan", "wizchan" }, host.Plugins.Sources.Select(source => source.Name).Order());
            var installed = await host.Plugins.ProfileStore.ReadAsync();
            Assert.Equal(7, installed.Plugins.Count);
            // 0.9 has no plugin identities yet: first discovery uses current Host
            // defaults, then subsequent normal restarts must preserve those values.
            string[] defaultOff = ["meowchan.source.kohlchan", "meowchan.source.wizchan", "meowchan.source.endchan"];
            Assert.All(installed.Plugins, plugin =>
            {
                Assert.Equal(!defaultOff.Contains(plugin.PluginId, StringComparer.Ordinal), plugin.Enabled);
                Assert.NotNull(plugin.Active); Assert.Null(plugin.Problem);
            });
            Dictionary<string, string> current = installed.Plugins.ToDictionary(plugin => plugin.PluginId, plugin => plugin.Active!.ExecutionRevision);
            if (revisions == null) revisions = current;
            else Assert.Equal(revisions.OrderBy(pair => pair.Key), current.OrderBy(pair => pair.Key));
            Assert.Empty(host.Plugins.Runtime.GetSnapshots());
            Assert.Equal(0, offline.Requests);
            Assert.True(host.Config.CompactDensity);
            Assert.Equal("Table", host.Config.ArchiveThreadLayout);
            Assert.Equal(431, host.Config.ArchiveSplitWidth);
            Assert.Equal(1123, host.Config.WindowWidth);
            Assert.Equal(Path.Combine(profile, "media"), host.Config.DownloadPath);
            Assert.Equal(Path.Combine(profile, "exports"), host.Config.LastExportDirectory);
            Assert.True(host.Config.SaveUrlsOnExit);
            Assert.Equal(3600, host.Config.RecheckTimer);
            Assert.Equal(2, host.GetView().Threads.Count);
            Assert.Equal(2, host.GetFavorites().Count);
            await using ArchiveReader reader = await host.OpenArchiveReaderAsync();
            foreach (JsonElement old in expected.GetProperty("Threads").EnumerateArray())
            {
                ResourceId id = old.GetProperty("Id").Deserialize<ResourceId>()!;
                var watch = Assert.Single(host.GetView().Threads, entry => entry.Snapshot.Id == id);
                Assert.Equal(old.GetProperty("Url").GetString(), watch.Snapshot.Url);
                var work = Assert.Single(host.GetThreadWorkSnapshots(), entry => entry.Url == watch.Snapshot.Url);
                Assert.Equal(MediaWorkStatus.Succeeded, Assert.Single(work.Media).Status);
                ArchivedThreadView view = (await reader.ReadThreadAsync(id))!;
                Assert.NotNull(view);
                IReadOnlyList<CapturedPost> migratedPosts = view.GetPosts();
                // Preserve every original receipt field, array and value. Only the two
                // additive nullable attachment properties are absent in the pinned 0.9 DTO.
                JsonArray expectedPosts = JsonNode.Parse(old.GetProperty("Posts").GetRawText())!.AsArray();
                foreach (JsonNode? post in expectedPosts)
                    foreach (JsonNode? node in post!["Attachments"]!.AsArray())
                    {
                        JsonObject attachment = node!.AsObject();
                        Assert.False(attachment.ContainsKey(nameof(CapturedAttachment.ExpectedSha256)));
                        Assert.False(attachment.ContainsKey(nameof(CapturedAttachment.AttachmentRevisionKey)));
                        attachment.Add(nameof(CapturedAttachment.ExpectedSha256), null);
                        attachment.Add(nameof(CapturedAttachment.AttachmentRevisionKey), null);
                    }
                Assert.All(migratedPosts.SelectMany(post => post.Attachments ?? Array.Empty<CapturedAttachment>()), attachment =>
                {
                    Assert.Null(attachment.ExpectedSha256);
                    Assert.Null(attachment.AttachmentRevisionKey);
                });
                Assert.True(JsonElement.DeepEquals(JsonSerializer.SerializeToElement(expectedPosts), JsonSerializer.SerializeToElement(migratedPosts)),
                    "Migrated posts differ from the old captured structure plus explicit null integrity defaults.");
                Assert.Equal(old.GetProperty("MediaDirectory").GetString(), view.Summary.MediaDirectory);
                MediaAssetReference asset = Assert.Single((await MediaAssetReader.OpenAsync(view.Summary.MediaDirectory)).GetPage());
                Assert.Equal(old.GetProperty("Asset").Deserialize<MediaAssetReference>(), asset);
                FavoriteEntry favorite = old.GetProperty("Favorite").Deserialize<FavoriteEntry>()!;
                Assert.Contains(favorite, host.GetFavorites());
                var verified = Assert.Single(await host.ExportHistory.ListVerifiedAsync(id));
                Assert.NotNull(verified.Inspection);
                Assert.Equal(old.GetProperty("Export").GetProperty("ExportId").GetGuid(), verified.Entry.ExportId);
                Assert.Equal(old.GetProperty("Export").GetProperty("Generation").GetInt32(), verified.Entry.Generation);
                // Re-export the migrated archive through 1.0 and verify the same original bytes.
                Directory.CreateDirectory(Path.Combine(profile, "reexport-" + startup));
                ArchiveHtmlExportResult fresh = await ArchiveHtmlExporter.ExportAsync(reader, id,
                    Path.Combine(profile, "reexport-" + startup, id.Source));
                Assert.Equal(2, fresh.PostCount);
                Assert.Equal(1, fresh.FileCount);
                Assert.Empty(fresh.Omissions);
            }
            foreach (JsonProperty file in expected.GetProperty("Files").EnumerateObject())
                Assert.Equal(file.Value.GetString(), Convert.ToHexString(SHA256.HashData(await File.ReadAllBytesAsync(Path.Combine(profile, file.Name)))));
            Assert.Equal(0, offline.Requests);
            await host.DisposeAsync().AsTask().WaitAsync(Deadline);
            Assert.Equal(DesktopSessionState.Stopped, host.State);
        }
        using ProfileLease lease = ProfileLease.Acquire(profile);
        WorkStateStore store = new(profile, lease);
        Assert.Equal(2, store.LoadResources().Count);
        foreach (WorkResource resource in store.LoadResources())
        {
            MediaWork media = Assert.Single(store.LoadMedia(resource.Url, resource.Generation));
            Assert.Equal("456", media.MediaIdentifier);
            Assert.Equal("original", media.Variant);
            Assert.Equal(MediaWorkStatus.Succeeded, media.Status);
        }
    }

    private sealed class RejectNetwork : HttpMessageHandler
    {
        internal int Requests;
        internal HttpClient Client() => new(this, disposeHandler: false);
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken token)
        {
            Interlocked.Increment(ref Requests);
            throw new InvalidOperationException("Offline upgrade attempted network: " + request.RequestUri);
        }
    }
}

public sealed class UpgradeFixtureFactAttribute : FactAttribute
{
    public UpgradeFixtureFactAttribute()
    {
        if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("MEOWCHAN_V09_UPGRADE_PROFILE")))
            Skip = "Requires a fresh pinned 0.9 profile from tests/fixtures/upgrade-v09/prepare.py; see its README.";
    }
}
